2058: func accumulatedToolCalls(accs map[int]*llamaServerToolCallAccumulator) ([]api.ToolCall, error) {
2059: 	if len(accs) == 0 {
2060: 		return nil, nil
2061: 	}
2062: 
2063: 	maxIndex := 0
2064: 	for index := range accs {
2065: 		maxIndex = max(maxIndex, index)
2066: 	}
2067: 
2068: 	toolCalls := make([]api.ToolCall, 0, len(accs))
2069: 	for index := 0; index <= maxIndex; index++ {
2070: 		acc := accs[index]
2071: 		if acc == nil {
2072: 			continue
2073: 		}
2074: 
2075: 		var args api.ToolCallFunctionArguments
2076: 		if strings.TrimSpace(acc.arguments) != "" {
2077: 			if err := json.Unmarshal([]byte(acc.arguments), &args); err != nil {
2078: 				return nil, fmt.Errorf("llama-server returned invalid tool call arguments for %q: %w", acc.name, err)
2079: 			}
2080: 		}
2081: 
2082: 		toolCalls = append(toolCalls, api.ToolCall{
2083: 			ID: acc.id,
2084: 			Function: api.ToolCallFunction{
2085: 				Index:     acc.index,
2086: 				Name:      acc.name,
2087: 				Arguments: args,
2088: 			},
2089: 		})
2090: 	}
2091: 
2092: 	return toolCalls, nil
2093: }
